import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"幻读与写偏斜","description":"","frontmatter":{"title":"幻读与写偏斜","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/phantom-write-skew.md","filePath":"cs/phantom-write-skew.md","lastUpdated":1789023840000}'),h={name:"cs/phantom-write-skew.md"};function B(c,a,A,_,m,S){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="幻读与写偏斜" tabindex="-1">幻读与写偏斜 <a class="header-anchor" href="#幻读与写偏斜" aria-label="Permalink to &quot;幻读与写偏斜&quot;">​</a></h1><div class="epigraph"><p>谓词读的集合里后来钻进新行，是幻读；两个事务各更新对方读过但自己没写的那一半，是写偏斜。</p><footer>—— 据 Eswaran 对谓词锁；Berenson et al. 对写偏斜；Gray</footer></div><p><a href="/cs/snapshot-isolation">上一课</a>给出 SI。本课不重做提交冲突。缺口是两种「点项锁看不见」的现象：幻读——范围扫描后插入满足谓词的新行；写偏斜——SI 下各写各的行，合起来违反不变量。后课隔离级别用这些异常当刻度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/rw-wr-ww">前向与后向冲突</a> 默认对象是已有元组。谓词读的对象是集合。插入是对集合的写，与先前的谓词读冲突，却没有 rid 可锁——除非间隙锁/谓词锁。SI 的快照让读稳定，但仍允许两名事务基于同一快照各改一行，提交后总和破坏约束。缺口是<strong>命名这两种缝</strong>。</p><p><span class="marginnote">写偏斜不是丢失更新：丢失更新是 ww 同一项。写偏斜是两个 ww 不重叠，但有 rw 环。本课只讲机制，不给利用步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>幻读防御：可串行隔离下对间隙加锁，或把插入当成冲突。写偏斜防御：真正可串行、SSI、或显式锁住不变量涉及的行（如把约束物化成一格计数）。应用层「再读一遍」不够，除非锁住。</p>',8)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E8%B0%93%E8%AF%8D%E8%AF%BB%22%5D%20--%3E%20PH%5B%22%E6%8F%92%E5%85%A5%E6%BB%A1%E8%B6%B3%E8%B0%93%E8%AF%8D%E7%9A%84%E6%96%B0%E8%A1%8C%3A%20%E5%B9%BB%22%5D%0A%20%20SI%5B%22%E5%90%8C%E4%B8%80%E5%BF%AB%E7%85%A7%E4%B8%8A%E5%90%84%E5%86%99%E4%B8%80%E8%A1%8C%22%5D%20--%3E%20WS%5B%22%E5%86%99%E5%81%8F%E6%96%9C%22%5D%0A%20%20PH%20--%3E%20GAP%5B%22%E9%97%B4%E9%9A%99%20%2F%20%E8%B0%93%E8%AF%8D%E9%94%81%22%5D%0A%20%20WS%20--%3E%20SER%5B%22%E5%8F%AF%E4%B8%B2%E8%A1%8C%E6%88%96%E6%98%BE%E5%BC%8F%E7%BA%A6%E6%9D%9F%E9%94%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>间隙锁把 B+ 叶上的空档变成可锁对象，与<a href="/cs/bplus-split">B+ 分裂</a> 交互：分裂要考虑锁。写偏斜说明「每行的 ww 检查」≠ 不变量。级别课会把这些放进 ANSI 表的批评里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每一种异常的 SQL 演示写成攻击教程。产品如何把级别标成 READ COMMITTED 等名字，下一课。</p><p>后课默认：幻与写偏斜是 SI/弱隔离的规格缝。级别是给应用的旋钮名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>幻读是谓词集合被插入改变。</li><li>写偏斜是 SI 上的 rw 环，不是同一行丢失更新。</li><li>隔离级别下一课。</li><li>出处：Eswaran 1976；Berenson et al. 1995。</li></ul>',7))])}const f=s(h,[["render",B]]);export{w as __pageData,f as default};
